-- Direct messages between two people. userA is always the lexicographically smaller
-- Clerk id, so a pair maps to exactly one thread.
CREATE TABLE IF NOT EXISTS "kvelpo_dm_thread" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "kvelpo_dm_thread_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"userA" varchar(256) NOT NULL,
	"userB" varchar(256) NOT NULL,
	"lastMessageAt" timestamp with time zone,
	"userALastReadAt" timestamp with time zone,
	"userBLastReadAt" timestamp with time zone,
	"createdAt" timestamp with time zone NOT NULL,
	CONSTRAINT "dm_thread_ordered_users" CHECK ("userA" < "userB")
);
CREATE UNIQUE INDEX IF NOT EXISTS "dm_thread_pair_idx" ON "kvelpo_dm_thread" ("userA", "userB");
CREATE INDEX IF NOT EXISTS "dm_thread_user_a_idx" ON "kvelpo_dm_thread" ("userA");
CREATE INDEX IF NOT EXISTS "dm_thread_user_b_idx" ON "kvelpo_dm_thread" ("userB");

CREATE TABLE IF NOT EXISTS "kvelpo_dm_message" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "kvelpo_dm_message_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"threadId" integer NOT NULL,
	"senderClerkUserId" varchar(256) NOT NULL,
	"message" text NOT NULL,
	"createdAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "dm_message_thread_idx" ON "kvelpo_dm_message" ("threadId", "createdAt");
DO $$ BEGIN
  ALTER TABLE "kvelpo_dm_message" ADD CONSTRAINT "kvelpo_dm_message_threadId_fk" FOREIGN KEY ("threadId") REFERENCES "kvelpo_dm_thread"("id") ON DELETE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
